CustomField.formula:
IF( OR(ISBLANK(Frequency__c), Frequency__c = "0"), "No Coverage", IF( Visits_Remaining__c <= 0, "Coverage Complete", IF( Sales_Cycle_End_Date__c - TODAY() <= 7, "Due This Week", CASE( Frequency__c,
/* ===== FREQ 3 ===== */ "3", IF( Completed_Visit_Count__c = 0, IF( TODAY() - Sales_Cycle_Start_Date__c >= 32, "Overdue", IF( TODAY() - Sales_Cycle_Start_Date__c >= 18, "Due This Week", IF( TODAY() - Sales_Cycle_Start_Date__c >= 10, "Upcoming", "Not Started" ) ) ), IF( ISBLANK(Last_Completed_Call_Date_Time__c), "Not Started", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) > 37, "Overdue", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) >= 30, "Due This Week", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) >= 23, "Upcoming", "Not Due Yet" ) ) ) ) ),
/* ===== FREQ 2 ===== */ "2", IF( Completed_Visit_Count__c = 0, IF( Sales_Cycle_End_Date__c - TODAY() <= 14, "Upcoming", "Not Started" ), IF( ISBLANK(Last_Completed_Call_Date_Time__c), "Not Started", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) > 49, "Overdue", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) >= 42, "Due This Week", IF( TODAY() - DATEVALUE(Last_Completed_Call_Date_Time__c) >= 35, "Upcoming", "Not Due Yet" ) ) ) ) ),
/* ===== FREQ 1 ===== */ "1", IF( Sales_Cycle_End_Date__c - TODAY() <= 14, "Upcoming", "Not Started" ),
"Not Started" ) ) ) )
